package com.waypointrs.sync;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Launches RuneLite with Waypoint Sync loaded, for personal/dev use.
 * Run from the CLI with:  ./gradlew runClient
 * or run this main() from your IDE.
 */
public class WaypointSyncPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(WaypointSyncPlugin.class);
		RuneLite.main(args);
	}
}

package com.waypointrs.sync;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.event.ActionListener;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

/**
 * Sidebar panel that shows the last sync at a glance, so a player can confirm their progress
 * reached Waypoint without opening the website. All display state is pushed in via {@link #update};
 * the plugin owns the data.
 */
class WaypointSyncPanel extends PluginPanel
{
	private final JLabel status = wrapLabel();
	private final JLabel account = wrapLabel();
	private final JLabel details = wrapLabel();
	private final JLabel server = wrapLabel();

	WaypointSyncPanel(Runnable onSyncNow, String siteUrl)
	{
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(12, 10, 12, 10));

		final JPanel box = new JPanel();
		box.setLayout(new BoxLayout(box, BoxLayout.Y_AXIS));
		box.setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JLabel title = new JLabel("Waypoint Sync");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);

		box.add(title);
		box.add(gap(8));
		box.add(status);
		box.add(gap(6));
		box.add(account);
		box.add(gap(10));

		// Totals, grouped in a subtle card so the numbers read as a block rather than loose lines.
		final JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(8, 9, 8, 9));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(details, BorderLayout.CENTER);
		box.add(card);
		box.add(gap(10));

		box.add(server);
		box.add(gap(14));

		box.add(fillWidth(button("Sync now", e -> onSyncNow.run())));
		box.add(gap(6));
		box.add(fillWidth(button("Open Waypoint", e -> LinkBrowser.browse(siteUrl))));

		add(box, BorderLayout.NORTH);
		update("Waiting for first sync…", "", "", "");
	}

	private static JButton button(String text, ActionListener onClick)
	{
		final JButton b = new JButton(text);
		b.addActionListener(onClick);
		return b;
	}

	/** Stretch a fixed-height component to the full panel width in a Y_AXIS BoxLayout, so buttons
	 *  fill the sidebar instead of floating at their natural (small, left) size. */
	private static <T extends JComponent> T fillWidth(T c)
	{
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		return c;
	}

	/** Push new display state. Safe to call from any thread. */
	void update(String statusText, String accountText, String detailsHtml, String serverText)
	{
		SwingUtilities.invokeLater(() -> {
			status.setText(statusText);
			account.setText(accountText);
			details.setText(detailsHtml);
			server.setText(serverText);
			account.setVisible(!accountText.isEmpty());
			details.setVisible(!detailsHtml.isEmpty());
			server.setVisible(!serverText.isEmpty());
		});
	}

	private static JLabel wrapLabel()
	{
		final JLabel l = new JLabel();
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		l.setForeground(ColorScheme.TEXT_COLOR);
		return l;
	}

	private static Component gap(int px)
	{
		return javax.swing.Box.createVerticalStrut(px);
	}
}

package com.waypointrs.sync;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.inject.Provides;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.ScriptID;
import net.runelite.api.Skill;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import java.awt.image.BufferedImage;
import java.text.SimpleDateFormat;
import java.util.Date;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Pushes account progression to waypointosrs.com.
 *
 * Sent on login and every few minutes after, and only while a token is configured: display name,
 * quest states, achievement diary and combat achievement varbits, skill levels and xp, collection
 * log counts and item names.
 *
 * Not sent: chat, bank, inventory, position, or anything about other players. The chat subscriber
 * below matches one game message ("New item added to your collection log") and ignores the rest.
 *
 * The endpoint is fixed at {@link #DEFAULT_URL}. With no token set, nothing is read and no
 * request is made.
 */
@Slf4j
@PluginDescriptor(
	name = "Waypoint Sync",
	description = "Uploads your quests, diaries, combat achievements, skills and collection log "
		+ "to your waypointosrs.com account. Requires an account; does nothing without a token.",
	tags = {"quest", "diary", "achievement", "tracker", "progress", "waypoint", "collection log"}
)
public class WaypointSyncPlugin extends Plugin
{
	/** Not a config item: there is one hosted instance, so there is nothing for a user to set. */
	private static final String DEFAULT_URL = "https://waypointosrs.com";

	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private WaypointSyncConfig config;
	@Inject private OkHttpClient httpClient;
	@Inject private Gson gson;
	@Inject private ScheduledExecutorService executor;
	@Inject private ClientToolbar clientToolbar;

	// Sidebar panel: lets a player confirm the last sync in-client, no website trip needed.
	private WaypointSyncPanel panel;
	private NavigationButton navButton;
	private volatile String statusText = "Waiting for first sync…";
	private volatile String accountText = "";
	private volatile String detailsText = "";
	private volatile String serverText = "";
	private volatile long lastSyncAt = 0L;

	/**
	 * Quest varbits stream in over several seconds after LOGGED_IN rather than being ready at
	 * once. Ingest is authoritative, so sending a half-loaded read clears quests that are actually
	 * finished. A fixed delay alone is a guess, so a read must also be stable: two consecutive
	 * reads have to agree before anything is sent.
	 */
	private static final int CONFIRM_DELAY_SECONDS = 5;

	private ScheduledFuture<?> periodic;
	private String lastQuestsJson;      // change-detection: avoid redundant posts
	private String pendingQuestsJson;   // previous read, awaiting confirmation

	// Panel "what's new" diff — the last SUCCESSFULLY synced state, plus a pending copy promoted on
	// success. Collection totals come from the last collection-log overview read this session.
	private Map<String, String> prevQuestStates;
	private Map<String, String> pendingQuestStates;
	private int lastCollObtained = -1, lastCollTotal = -1;

	// A running, named log of what synced THIS session (quests from the sync diff; combat tasks and
	// collection items from their live pop-ups). Persists for the whole session — a later "nothing
	// changed" sync never wipes it. Cleared only when the plugin (re)starts.
	private final java.util.List<String> sessionLog = new java.util.ArrayList<>();
	// Last real level seen per skill, so onStatChanged can tell an actual level-up from the XP drops
	// that fire constantly. Rebuilt from scratch on each login — see onGameStateChanged.
	private final Map<Skill, Integer> lastLevels = new EnumMap<>(Skill.class);
	// Authoritative counts echoed by the server's ingest response — lets the panel show real totals
	// (esp. collection) without the player re-opening the collection log in-game every login.
	private int srvQuests = -1, srvMini = -1, srvCombat = -1, srvColl = -1, srvSkills = -1;

	// RuneLite's Quest enum mixes miniquests in with quests and does NOT prefix them (the "MQ:" the
	// player sees is in the in-game quest journal, not the API). These are the enum entries that are
	// actually miniquests, so the panel can count and label them separately from real quests.
	private static final java.util.Set<String> MINIQUESTS = new java.util.HashSet<>(java.util.Arrays.asList(
		"Alfred Grimhand's Barcrawl", "Barbarian Training", "Bear Your Soul", "Curse of the Empty Lord",
		"Daddy's Home", "Enter the Abyss", "Family Pest", "His Faithful Servants", "Hopespear's Will",
		"In Search of Knowledge", "Into the Tombs", "Lair of Tarn Razorlor", "Mage Arena I", "Mage Arena II",
		"Skippy and the Mogres", "The Enchanted Key", "The Frozen Door", "The General's Shadow", "Vale Totems"));

	// Recipe for Disaster: one quest, but the enum carries its 11 sub-parts separately.
	private static final String RFD_PREFIX = "Recipe for Disaster - ";
	private static final String RFD_FINAL = "Recipe for Disaster - Culinaromancer";

	/** Collection log pages seen this session: page title -> {obtained,total}. */
	private final Map<String, JsonObject> collectionPages = new LinkedHashMap<>();

	/** Combat achievement task name -> the filter value in force when it was seen. */
	private final Map<String, Integer> caSeen = new LinkedHashMap<>();
	private int caTickCounter;
	private String lastGroupsSig;
	private String lastScreenSig;
	private final java.util.Set<String> warnedGroups = new java.util.HashSet<>();
	private boolean syncedThisSession;

	/** Overview groups: Bosses/Raids/Clues/Minigames/Other -> {obtained,total}. */
	private final Map<String, JsonObject> collectionGroups = new LinkedHashMap<>();

	/** Item name -> raw widget opacity, or -1 when the game announced it in chat. */
	private final Map<String, Integer> collectionItems = new LinkedHashMap<>();

	@Provides
	WaypointSyncConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(WaypointSyncConfig.class);
	}

	@Override
	protected void startUp()
	{
		lastQuestsJson = null;
		pendingQuestsJson = null;
		collectionPages.clear();
		collectionGroups.clear();
		collectionItems.clear();
		clogRetrieving = false;
		clogLastEntryTick = -1;
		clogRequestedTick = -1;
		clogNewThisBurst = 0;
		clogEntriesThisBurst = 0;
		clogObtainedThisBurst = 0;
		clogBurstObtained.clear();
		clogComplete = null;
		caSeen.clear();
		sessionLog.clear();
		syncedThisSession = false;
		caTickCounter = 0;
		// Sidebar panel + toolbar icon.
		if (navButton == null)
		{
			panel = new WaypointSyncPanel(this::forceSync, baseUrl());
			final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
			navButton = NavigationButton.builder()
				.tooltip("Waypoint Sync")
				.icon(icon)
				.priority(8)
				.panel(panel)
				.build();
			clientToolbar.addNavigation(navButton);
		}
		if (config.token() == null || config.token().isEmpty())
		{
			statusText = "No token set — paste one in the plugin settings.";
		}
		refreshPanel();

		// Log whether a token is present, never the token itself.
		log.debug("Waypoint Sync started (token {})",
			config.token() == null || config.token().isEmpty() ? "missing" : "set");
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			// Already logged in when the plugin started, so the client is settled: no delay.
			scheduleSync(0);
		}
		int mins = config.syncIntervalMinutes();
		if (mins > 0)
		{
			periodic = executor.scheduleWithFixedDelay(() -> {
				if (client.getGameState() == GameState.LOGGED_IN)
				{
					scheduleSync(0);
				}
			}, mins, mins, TimeUnit.MINUTES);
		}
	}

	@Override
	protected void shutDown()
	{
		if (periodic != null)
		{
			periodic.cancel(true);
			periodic = null;
		}
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
			panel = null;
		}
	}

	/** Manual "Sync now" from the panel — clear the change-detection cache so it always re-sends. */
	private void forceSync()
	{
		lastQuestsJson = null;
		statusText = "Syncing…";
		refreshPanel();
		scheduleSync(0);
	}

	/** Rebuild the panel's display from the current status fields. */
	private void refreshPanel()
	{
		if (panel == null)
		{
			return;
		}
		String status = statusText;
		if (lastSyncAt > 0)
		{
			status += "  (" + new SimpleDateFormat("HH:mm").format(new Date(lastSyncAt)) + ")";
		}
		final String acct = accountText.isEmpty() ? "" : "Account: " + accountText;
		panel.update(status, acct, detailsText, serverText);
	}

	/** The "tracking on Waypoint" totals block. Width-boxed so long lines wrap on a narrow panel
	 *  instead of clipping. The collection line is passed in because its best source differs: the
	 *  server's authoritative stored count (from the ingest response) when available, else a
	 *  plugin-side read of the log this session. */
	// Sync-state footer for the totals card. Reliable because it keys on the plugin's own change
	// detection (current snapshot vs the last SUCCESSFULLY posted one), not a count comparison — a
	// raw count would false-positive on quests the RuneLite enum reports but our content can't map.
	private static final String SYNC_OK   = "<font color='#8fbf7f'>Everything synced &#10003;</font>";
	private static final String SYNC_BUSY = "<font color='#e0b24c'>Syncing new progress…</font>";

	private static String buildStatsHtml(int quests, int mini, int combat, String collLine, int skills,
		String chartLine, String health)
	{
		return "<html><div style='width:190px'>"
			+ "<b>" + quests + "</b> quests"
			+ (mini > 0 ? " &middot; <b>" + mini + "</b> miniquests" : "") + "<br>"
			+ "<b>" + fmtInt(combat) + "</b> combat tasks<br>"
			+ collLine + "<br>"
			+ "<b>" + skills + "</b> skills"
			+ (chartLine.isEmpty() ? "" : "<br>" + chartLine)
			+ (health.isEmpty() ? "" : "<br>" + health)
			+ "</div></html>";
	}

	/**
	 * "25/358 sea charts". Counted from the varbits just read rather than echoed back by the
	 * server, so it is correct on the very first sync. Empty when the client reports no charting
	 * varbits at all, so a pre-Sailing client shows nothing instead of a bare "0".
	 */
	private static String chartLine(JsonObject charting)
	{
		if (charting == null || charting.size() == 0)
		{
			return "";
		}
		int done = 0;
		for (String k : charting.keySet())
		{
			if (charting.get(k).getAsInt() > 0)
			{
				done++;
			}
		}
		return "<b>" + fmtInt(done) + "</b>/" + fmtInt(charting.size()) + " sea charts";
	}

	/** Append newly-FINISHED quests (vs the last synced snapshot) to the session log. Combat tasks
	 *  and collection items add themselves live from their pop-ups, so this covers only quests. */
	private void logNewQuests(JsonObject quests)
	{
		if (prevQuestStates == null)
		{
			return;   // first sync = baseline; don't dump the whole account into the log
		}
		for (String qn : quests.keySet())
		{
			if (!"FINISHED".equals(quests.get(qn).getAsString()) || "FINISHED".equals(prevQuestStates.get(qn)))
			{
				continue;
			}
			if (qn.startsWith(RFD_PREFIX))
			{
				if (!qn.equals(RFD_FINAL))
				{
					continue;   // the individual RFD parts aren't separate quest completions
				}
				logSession("Recipe for Disaster");
				continue;
			}
			logSession((MINIQUESTS.contains(qn) ? "Miniquest: " : "Quest: ") + qn);
		}
	}

	/** Add a named entry to the running session log (most-recent first), then refresh the panel.
	 *  De-duplicates so a re-sync of the same state can't double-list something. */
	private void logSession(String entry)
	{
		if (sessionLog.contains(entry))
		{
			return;
		}
		sessionLog.add(0, entry);
		serverText = buildSessionLogHtml();
		refreshPanel();
	}

	/** The session log for the panel — everything synced since the plugin started, newest first. */
	private String buildSessionLogHtml()
	{
		if (sessionLog.isEmpty())
		{
			return "<html><div style='width:190px'>First sync — captured everything. &#10003;</div></html>";
		}
		final int cap = 8;
		final StringBuilder sb = new StringBuilder("<html><div style='width:190px'><b>This session</b><br>");
		for (int i = 0; i < sessionLog.size() && i < cap; i++)
		{
			sb.append("&bull; ").append(htmlEscape(sessionLog.get(i))).append("<br>");
		}
		if (sessionLog.size() > cap)
		{
			sb.append("&bull; +").append(sessionLog.size() - cap).append(" more");
		}
		return sb.append("</div></html>").toString();
	}

	private static String questState(JsonObject quests, String name)
	{
		return quests.has(name) && !quests.get(name).isJsonNull() ? quests.get(name).getAsString() : "";
	}

	private static Map<String, String> snapshotStates(JsonObject quests)
	{
		final Map<String, String> m = new java.util.HashMap<>();
		for (String qn : quests.keySet())
		{
			m.put(qn, quests.get(qn).getAsString());
		}
		return m;
	}

	private static String fmtInt(int n)
	{
		return String.format("%,d", n);
	}

	/** Collection line for the totals block. Prefer the server's authoritative stored count (so no
	 *  in-game log open is needed), then a log read from this session, then a gentle first-run hint. */
	private String collLine()
	{
		if (srvColl >= 0)
		{
			return "<b>" + fmtInt(srvColl) + "</b> collection log slots";
		}
		if (lastCollObtained >= 0 && lastCollTotal > 0)
		{
			return "<b>" + fmtInt(lastCollObtained) + "</b> / " + fmtInt(lastCollTotal) + " collection log";
		}
		return "Collection log — open it once to sync";
	}

	private static int optInt(JsonObject o, String k, int def)
	{
		try
		{
			return o.has(k) && !o.get(k).isJsonNull() ? o.get(k).getAsInt() : def;
		}
		catch (RuntimeException e)
		{
			return def;
		}
	}

	private static String htmlEscape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Re-arm only when the player has genuinely left the world. LOADING is NOT that: it fires on
		// every region cross, teleport and staircase, and Sailing's travel cycles LOADING/LOGGED_IN
		// continuously. Treating it as a logout made each of those look like a fresh login and fire
		// a full sync — which is the login path, so it bypasses the burst coalescing entirely.
		final GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING
			|| state == GameState.CONNECTION_LOST)
		{
			syncedThisSession = false;   // re-arm for the next login
			caTickCounter = 0;
			// Drop the level baseline too. Logging back in on a different character would otherwise
			// diff its levels against the previous one and report a screenful of "level-ups".
			lastLevels.clear();
		}
		if (state == GameState.LOGGED_IN && config.syncOnLogin() && !syncedThisSession)
		{
			pendingQuestsJson = null;   // a fresh login invalidates any half-read snapshot
			watchingInterfaces = false;
			syncedThisSession = true;   // event path worked, no tick fallback needed
			scheduleSync(Math.max(0, config.loginDelaySeconds()));
		}
	}

	/**
	 * Level-ups: name them in the session log, and sync promptly rather than waiting for the timer.
	 *
	 * StatChanged fires on every XP drop, which is far too often to act on, so this compares the
	 * REAL level against the last one seen and ignores everything else. The first event per skill
	 * only establishes the baseline — otherwise logging in would report all 24 skills as level-ups.
	 *
	 * Levels used to reach the site only on the periodic sync (default every 5 minutes), and never
	 * appeared in the session log at all: quests came from the sync diff, combat tasks and
	 * collection items from their pop-ups, and levels from nothing. So the panel could sit on
	 * "Everything synced" having never looked since the level was gained. The sync is coalesced
	 * because a single combat level-up changes two skills at once.
	 */
	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		final Skill skill = event.getSkill();
		if (skill == null)
		{
			return;
		}
		final int level = event.getLevel();
		final Integer prev = lastLevels.put(skill, level);
		if (prev == null || prev == level)
		{
			return;   // baseline for this skill, or XP with no level change
		}
		if (level > prev)
		{
			logSession("Level: " + skill.getName() + " " + level);
		}
		scheduleSyncCoalesced();
	}

	/**
	 * Capture a collection log page when one is opened.
	 *
	 * Per-item state is not in varbits (56 of ~1500 items have dedicated ones, plus 124 category
	 * flags), so the counts only exist in the interface, and only for a page the client has drawn.
	 * Whatever page is opened gets scraped and kept server-side.
	 *
	 * Matches on the "Obtained: x/y" label rather than widget child ids, which shift between game
	 * updates.
	 */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		// Opening the log is the cue to ask for all of it at once. The widget capture below still
		// runs: it is what fills in per-page obtained/total, which the transmitted entries do not
		// carry, and it costs nothing on a page that is on screen anyway.
		if (event.getScriptId() == COLLECTION_SETUP)
		{
			requestWholeCollectionLog();
			return;
		}
		if (event.getScriptId() != ScriptID.COLLECTION_DRAW_LIST)
		{
			return;
		}
		try
		{
			captureCollectionPage();
			captureCollectionItems();
		}
		catch (Exception ex)
		{
			log.warn("Waypoint: collection log capture failed", ex);
		}
	}

	/** Interfaces are small; scanning past the end just yields nulls. */
	private static final int MAX_INTERFACE_CHILDREN = 80;

	/** How often to check for an interface we have had no WidgetLoaded for. ~6s at 0.6s/tick. */
	private static final int SLOW_INTERFACE_POLL_TICKS = 10;

	/** Set by WidgetLoaded for a group we capture from; cleared once none of them is open. */
	private volatile boolean watchingInterfaces;

	/**
	 * The charting line from the sync currently in flight. The success handler rebuilds the stats
	 * card from the server's confirmed totals, and the server does not echo charting back — so it
	 * is remembered here rather than dropped, which would make the line flicker away on every
	 * successful sync.
	 */
	private volatile String lastChartLine = "";

	/**
	 * Charting descriptions seen since the last successful post.
	 *
	 * The varbits say a task went from 0 to 1 but only as TYPE_LOCATION; the pop-up says what the
	 * task actually was, in words. Sending both together lets the server pair them up — on the sync
	 * a task completes, exactly one charting varbit flips, so the description belongs to that key.
	 * That is the only way to learn the wording of tasks whose key names something the wiki text
	 * never mentions (crate tasks are keyed by the drink inside, which the task deliberately does
	 * not spoil).
	 *
	 * Cleared only after a successful post, so a failed sync does not lose the pairing.
	 */
	private final List<String> chartedSincePost = Collections.synchronizedList(new ArrayList<>());

	/** Tab order as the game indexes them in COLLECTION_LAST_TAB. */
	private static final String[] TAB_NAMES = { "Bosses", "Raids", "Clues", "Minigames", "Other" };

	/** The five top-level tabs on the collection log overview. */
	private static final java.util.Set<String> GROUPS = new java.util.HashSet<>(
		java.util.Arrays.asList("Bosses", "Raids", "Clues", "Minigames", "Other"));
	/** A bare "7/336" cell. */
	private static final Pattern COUNT = Pattern.compile("(\\d+)\\s*/\\s*(\\d+)");

	private static final Pattern OBTAINED = Pattern.compile("Obtained:\\s*(\\d+)\\s*/\\s*(\\d+)");
	/** The window header, e.g. "Collection Log - 61/1706". Whole-log progress, not a page. */
	private static final Pattern HEADER = Pattern.compile("Collection Log\\s*-\\s*(\\d+)\\s*/\\s*(\\d+)");

	/**
	 * Combat achievement tasks, read from the Tasks interface.
	 *
	 * Per-task completion is not readable as a varbit: the named CA_TASK_*_COMPLETED entries cover
	 * about 63% of tasks, and the 640-bit varplayer bitmap has no published task to bit mapping.
	 * The interface renders every task by name and the active filter is exposed as a varbit, so
	 * reading the screen is exact.
	 *
	 * Polled on a tick while the interface is open, since scrolling reveals more rows without
	 * firing a load event. Names accumulate across scrolls.
	 */
	/**
	 * Start watching as soon as one of the interfaces we read from opens. Cheap and immediate —
	 * it replaces polling for the answer, and means a page opened between slow polls is still
	 * captured straight away.
	 */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		final int g = event.getGroupId();
		if (g == InterfaceID.COLLECTION || g == InterfaceID.COLLECTION_OVERVIEW || g == InterfaceID.CA_TASKS)
		{
			watchingInterfaces = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		try
		{
			flushCollectionBurst();
			gameTick();
		}
		catch (Throwable t)
		{
			if (warnedGroups.add("tick"))
			{
				log.warn("Waypoint: tick handler failed ({})", t.getClass().getSimpleName(), t);
			}
		}
	}

	private void gameTick()
	{
		caTickCounter++;

		// Fallback for the login sync. GameStateChanged is dispatched to subscribers in sequence
		// and an exception in one aborts the rest, so an unrelated plugin throwing in onLogin can
		// stop LOGGED_IN reaching this one. Ticks are not affected by that.
		if (!syncedThisSession && client.getGameState() == GameState.LOGGED_IN
			&& client.getLocalPlayer() != null
			&& caTickCounter > Math.max(1, config.loginDelaySeconds()) / 2)
		{
			syncedThisSession = true;
			log.debug("Waypoint: login sync (tick fallback)");
			scheduleSync(0);
		}

		// interfaceOpen() probes up to MAX_INTERFACE_CHILDREN widgets per group, and the miss case
		// (nothing open) always runs the full loop. Polling three groups every other tick therefore
		// cost hundreds of widget lookups per second for the whole session, almost always to
		// discover that nothing was open.
		//
		// WidgetLoaded tells us the moment one of them opens, so the frequent poll now runs only
		// while a relevant interface is actually up. The slow poll is kept as a safety net: if a
		// WidgetLoaded were ever missed, capture resumes within a few seconds instead of not at all.
		final boolean poll = watchingInterfaces
			? caTickCounter % 2 == 0
			: caTickCounter % SLOW_INTERFACE_POLL_TICKS == 0;
		if (!poll)
		{
			return;
		}

		// The overview does not fire COLLECTION_DRAW_LIST, so poll for it here. Without its
		// per-group totals the server has to sum pages instead, which double-counts drops shared
		// between logs.
		final boolean collectionUp = interfaceOpen(InterfaceID.COLLECTION)
			|| interfaceOpen(InterfaceID.COLLECTION_OVERVIEW);
		final boolean caUp = interfaceOpen(InterfaceID.CA_TASKS);
		// Nothing of ours is on screen any more — stop the fast poll until the next WidgetLoaded.
		watchingInterfaces = collectionUp || caUp;
		if (collectionUp)
		{
			try
			{
				captureCollectionPage();
				captureCollectionItems();
			}
			catch (Exception ex)
			{
				log.debug("Waypoint: collection poll failed", ex);
			}
		}
		// Probe a range of children rather than gating on child 0: an interface's root child is
		// not necessarily 0.
		if (!caUp)
		{
			if (caTickCounter % 20 == 0 && interfaceOpen(InterfaceID.CA_OVERVIEW))
			{
				log.debug("Waypoint: CA overview is open but the Tasks list is not. "
					+ "Open the Tasks tab and set Completed=Complete to record finished tasks.");
			}
			return;
		}
		try
		{
			captureCombatTasks();
		}
		catch (Exception ex)
		{
			log.debug("Waypoint: combat task capture failed", ex);
		}
	}

	/** True if any child of the group is loaded. Interfaces do not reliably use child 0. */
	private boolean interfaceOpen(int group)
	{
		for (int child = 0; child < MAX_INTERFACE_CHILDREN; child++)
		{
			if (client.getWidget(group, child) != null)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The 20 varps holding the per-task completion bitmap. Listed explicitly because the ids are
	 * not consecutive: 0..12 run 3116-3128, then 3387, 3718, 3773, 3774, 4204, 4496, 4721.
	 * Reading them as base+i picks up bits from unrelated varps.
	 */
	private static final int[] CA_TASK_VARPS = {
		VarPlayerID.CA_TASK_COMPLETED_0,  VarPlayerID.CA_TASK_COMPLETED_1,
		VarPlayerID.CA_TASK_COMPLETED_2,  VarPlayerID.CA_TASK_COMPLETED_3,
		VarPlayerID.CA_TASK_COMPLETED_4,  VarPlayerID.CA_TASK_COMPLETED_5,
		VarPlayerID.CA_TASK_COMPLETED_6,  VarPlayerID.CA_TASK_COMPLETED_7,
		VarPlayerID.CA_TASK_COMPLETED_8,  VarPlayerID.CA_TASK_COMPLETED_9,
		VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13,
		VarPlayerID.CA_TASK_COMPLETED_14, VarPlayerID.CA_TASK_COMPLETED_15,
		VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
		VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19,
	};

	/**
	 * The raw combat achievement bitmap: 21 varplayers, one bit per task, in id order.
	 *
	 * This is the whole per-task answer and it costs nothing — it is readable at login with no
	 * interface open, no scrolling and no filter dropdown to misread. It used to be collapsed to
	 * a popcount here because the task-to-bit mapping was assumed unavailable; it is not, the wiki
	 * publishes it as data-ca-task-id, and the server now holds it. Sent raw and decoded there, so
	 * a new task never needs a plugin release to be understood.
	 */
	private JsonArray combatTaskBits()
	{
		final JsonArray out = new JsonArray();
		for (int varp : CA_TASK_VARPS)
		{
			out.add(client.getVarpValue(varp));
		}
		return out;
	}

	/**
	 * Number of completed combat achievement tasks. Still sent for the server's own cross-check,
	 * and as the only signal for a server that does not understand the bitmap.
	 */
	private int completedTaskCount()
	{
		int set = 0;
		for (int varp : CA_TASK_VARPS)
		{
			set += Integer.bitCount(client.getVarpValue(varp));
		}
		return set;
	}

	private void captureCombatTasks()
	{
		// The "Completed" dropdown, 0/1/2. Recorded raw and interpreted server-side.
		final int filter = client.getVarbitValue(VarbitID.CA_TASK_FILTER_COMPLETED);

		final java.util.List<String> texts = new java.util.ArrayList<>();
		for (int child = 0; child < MAX_INTERFACE_CHILDREN; child++)
		{
			collectText(client.getWidget(InterfaceID.CA_TASKS, child), texts, 0);
		}
		if (texts.isEmpty())
		{
			if (caTickCounter % 20 == 0)
			{
				log.debug("Waypoint: CA Tasks interface open but no text read yet.");
			}
			return;
		}

		// No attempt to infer the row structure. The server holds all 637 task names already, so
		// every plausible string is sent and matched there. That survives a relayout of the
		// interface, which positional parsing would not.
		int added = 0;
		for (final String t : texts)
		{
			final String name = t.trim();
			if (name.isEmpty() || name.length() > 60
				|| name.startsWith("Monster:") || name.endsWith(":"))
			{
				continue;
			}
			// Keep the STRONGEST filter a name was ever seen under, not just the first. The list
			// opens on "Completed: All", so a task first sighted there is recorded as not-complete;
			// putIfAbsent would then refuse to upgrade it when the user switches to "Complete",
			// leaving genuinely finished tasks stuck. "Complete" is the highest filter value, so
			// max-merge lets a later Complete sighting win. A change re-triggers the sync.
			final Integer prev = caSeen.get(name);
			if (prev == null || filter > prev)
			{
				caSeen.put(name, filter);
				added++;
			}
		}
		if (added > 0)
		{
			log.debug("Waypoint: captured {} combat task name(s), filter={} (total {})",
				added, filter, caSeen.size());
			scheduleSyncCoalesced();
		}
		else if (caTickCounter % 40 == 0)
		{
			log.debug("Waypoint: CA Tasks open, {} strings on screen, {} names held, filter={}",
				texts.size(), caSeen.size(), filter);
		}
	}

	/** Depth-first, document order, colour tags stripped. Depth-guarded against cycles. */
	private void collectText(Widget w, java.util.List<String> out, int depth)
	{
		if (w == null || depth > 8 || out.size() > 400)
		{
			return;
		}
		final String raw = w.getText();
		if (raw != null && !raw.isEmpty())
		{
			final String text = raw.replaceAll("<[^>]*>", "").trim();
			if (!text.isEmpty())
			{
				out.add(text);
			}
		}
		for (Widget[] kids : new Widget[][]{ w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren() })
		{
			if (kids != null)
			{
				for (Widget k : kids)
				{
					collectText(k, out, depth + 1);
				}
			}
		}
	}

	/**
	 * Collection log item tracking, from three sources of differing confidence.
	 *
	 * The "New item" pop-up ({@link #onScriptPreFired}) is the primary live signal: it shows for the
	 * local player whenever an entry is gained, independent of clan membership or chat settings, and
	 * carries no other player's name. The chat line below is a secondary catch for players whose
	 * notification is set to chat only. Opening a log page renders its items with unobtained ones
	 * dimmed, which backfills everything obtained before the plugin was installed.
	 *
	 * Opacity is sent raw and interpreted server-side, since its exact meaning is an assumption.
	 */
	private static final Pattern COLLOG_CHAT =
		Pattern.compile("New item added to your collection log:\\s*(.+?)\\s*$");

	/** The game's collection-log pop-up sets this as its title line. */
	private static final String COLLOG_POPUP_TITLE = "Collection log";

	/**
	 * "Charting Complete!" — shown the moment a sea charting task is finished, with the task's
	 * description as the body ("Find some curious rapids west of Rock Island Prison").
	 *
	 * The completion itself already arrives as a varbit, so this is not how charting is tracked.
	 * It is here for the session log: the varbits say a count went up, this says WHICH one, and a
	 * panel that names what you just did is the difference between "26/358" and "Charted: Find some
	 * curious rapids west of Rock Island Prison". The description is also the only human-readable
	 * form of a task the client ever gives us — the varbit is just TYPE_LOCATION.
	 */
	private static final String CHARTING_POPUP_TITLE = "charting complete";
	/** ...and prefixes the item name in the body with this. */
	private static final String COLLOG_POPUP_PREFIX = "New item:";

	/**
	 * Collection log, in one open instead of 124.
	 *
	 * The log's own Search option needs every entry, so asking for it makes the server transmit the
	 * whole log; each entry then arrives as a {@link #COLLECTION_TRANSMIT} script fire carrying an
	 * item id and a quantity. Re-running the setup script closes the search again, so the player
	 * sees their log exactly as they left it.
	 *
	 * This replaces reading the rendered widgets, which could only ever see pages the player had
	 * personally opened — in practice most accounts had a handful of the 124, and the rest of the
	 * log simply did not exist as far as Waypoint was concerned.
	 */
	private static final int COLLECTION_TRANSMIT = 4100;   // fires once per entry
	private static final int COLLECTION_SETUP    = 7797;   // fires when the log is opened
	private static final int COLLECTION_INIT     = 2240;   // re-run to close the search we opened

	/** True while OUR search is running, so the setup it re-fires does not start another one. */
	private boolean clogRetrieving;
	/** Tick of the most recent entry, so the burst can be allowed to finish before syncing. */
	private int clogLastEntryTick = -1;
	/** Tick the request went out, so a request that yields nothing can time out rather than latch. */
	private int clogRequestedTick = -1;
	// Counted per burst purely so the debug line can distinguish "nothing arrived" from "everything
	// arrived and was already known" — two very different failures that otherwise look identical.
	private int clogEntriesThisBurst;
	private int clogObtainedThisBurst;
	/** Names from the burst in progress. */
	private final java.util.Set<String> clogBurstObtained = new java.util.LinkedHashSet<>();
	/**
	 * The last COMPLETE transmit. Held separately from the in-progress set so a burst that is
	 * still arriving — or one that was cut short — can never be reported as a total; the server
	 * replaces the stored collection from this, so "partial" and "complete" must not be confusable.
	 */
	private java.util.Set<String> clogComplete;

	/**
	 * The log can also be opened through another player's house adventure log, in which case every
	 * entry that arrives belongs to THEM. Recording those against this account would be silent,
	 * plausible-looking corruption, so nothing is captured while this is set.
	 */
	private boolean viewingSomeoneElsesLog()
	{
		return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
	}

	private void requestWholeCollectionLog()
	{
		if (clogRetrieving || viewingSomeoneElsesLog())
		{
			return;
		}
		clogRetrieving = true;
		clogRequestedTick = client.getTickCount();
		clogEntriesThisBurst = 0;
		clogObtainedThisBurst = 0;
		clogBurstObtained.clear();
		log.debug("Waypoint: collection log opened — requesting the full transmit");
		// Ask for the whole log, then put the interface back the way it was.
		client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1,
			"Search", null);
		client.runScript(COLLECTION_INIT);
	}

	/**
	 * One entry of the transmitted collection log.
	 *
	 * The script fires for EVERY slot, obtained or not, and the quantity is what separates them —
	 * a zero means the player has never had one. Treating a fire as proof of ownership would mark
	 * the entire log collected.
	 *
	 * The server stores collection items by name, so the id is resolved here: this runs on the
	 * client thread (a script fire always does), which is the only place item definitions may be
	 * read.
	 */
	private void collectionEntry(ScriptPreFired event)
	{
		if (viewingSomeoneElsesLog())
		{
			return;
		}
		final Object[] args = event.getScriptEvent() == null
			? null : event.getScriptEvent().getArguments();
		if (args == null || args.length < 3)
		{
			return;
		}

		clogLastEntryTick = client.getTickCount();
		clogEntriesThisBurst++;

		final int itemId;
		final int quantity;
		try
		{
			itemId = (int) args[1];
			quantity = (int) args[2];
		}
		catch (ClassCastException e)
		{
			return;   // interface reshuffled; better to capture nothing than to capture nonsense
		}
		if (quantity <= 0)
		{
			return;   // a slot the player has never filled
		}
		clogObtainedThisBurst++;

		final String name = client.getItemDefinition(itemId).getName();
		if (name == null || name.isEmpty() || "null".equals(name))
		{
			return;
		}
		// -1 is the "proven obtained" sentinel the pop-up path already uses, as opposed to a
		// widget opacity that only suggests it.
		clogBurstObtained.add(name);
		if (collectionItems.put(name, -1) == null)
		{
			clogNewThisBurst++;
		}
	}

	/** Entries arrive in a burst; sync once it has finished rather than on every one of ~1500. */
	private int clogNewThisBurst;

	/**
	 * Ticks to wait for the first entry before giving up on a request.
	 *
	 * Without this the in-progress flag latches: if the request produces nothing — the menu action
	 * does not take, the interface has moved, the player closes the log immediately — every later
	 * open returns early and the collection log silently stops syncing until the client restarts.
	 * Timing out instead means the worst case is one missed open.
	 */
	private static final int CLOG_REQUEST_TIMEOUT_TICKS = 10;

	private void flushCollectionBurst()
	{
		if (clogLastEntryTick == -1)
		{
			if (clogRetrieving && client.getTickCount() > clogRequestedTick + CLOG_REQUEST_TIMEOUT_TICKS)
			{
				log.debug("Waypoint: collection log request produced nothing; will retry on next open");
				clogRetrieving = false;
			}
			return;
		}
		if (client.getTickCount() < clogLastEntryTick + 2)
		{
			return;
		}
		clogLastEntryTick = -1;
		clogRetrieving = false;
		// Promote only now, once the burst has demonstrably finished.
		clogComplete = new java.util.LinkedHashSet<>(clogBurstObtained);
		log.debug("Waypoint: collection log transmit finished — {} entries, {} obtained, {} new, {} held",
			clogEntriesThisBurst, clogObtainedThisBurst, clogNewThisBurst, collectionItems.size());
		clogNewThisBurst = 0;
		scheduleSyncCoalesced();
	}

	/** The combat-achievement pop-up ("Combat Task Completed!" / "Task Completed: NAME (N points)").
	 *  It rides the same NOTIFICATION_START script as the collection-log pop-up, so a finished task
	 *  can be captured live — no need to open and scroll the Tasks interface for tasks done while the
	 *  plugin is running. The interface scrape remains only as a backfill for older completions. */
	private static final Pattern COMBAT_POPUP_BODY =
		Pattern.compile("(?i)Task Completed:\\s*(.+?)\\s*\\(\\d+\\s*points?\\)\\s*$");
	/** CA Tasks "Completed" filter value the server treats as done (observed live). */
	private static final int CA_FILTER_COMPLETE = 2;

	/**
	 * The "New item" pop-up box. It fires for the local player regardless of whether they are in a
	 * clan or have chat notifications enabled, so it catches gains that never reach the chat box.
	 * The pop-up's title is "Collection log" and its body reads "New item: &lt;name&gt;".
	 */
	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() == COLLECTION_TRANSMIT)
		{
			collectionEntry(event);
			return;
		}
		if (event.getScriptId() != ScriptID.NOTIFICATION_START)
		{
			return;
		}
		final String title = client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE);
		final String main = client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN);
		if (title == null || main == null)
		{
			return;
		}
		final String body = main.replaceAll("<[^>]*>", " ").trim();
		// Same de-tagging for the title: these headings are colour-formatted, and an unstripped
		// "<col=ff981f>Charting Complete!</col>" would never match a plain-text comparison.
		final String plainTitle = title.replaceAll("<[^>]*>", " ").trim();

		// Collection-log "New item" pop-up.
		if (title.trim().equalsIgnoreCase(COLLOG_POPUP_TITLE))
		{
			String item = body;
			if (item.regionMatches(true, 0, COLLOG_POPUP_PREFIX, 0, COLLOG_POPUP_PREFIX.length()))
			{
				item = item.substring(COLLOG_POPUP_PREFIX.length()).trim();
			}
			if (item.isEmpty())
			{
				return;
			}
			// -1 marks "confirmed by the game itself", distinct from any opacity value.
			collectionItems.put(item, -1);
			logSession("Collection: " + item);
			log.debug("Waypoint: collection log pop-up '{}' (now holding {} item states)",
				item, collectionItems.size());
			scheduleSyncCoalesced();
			return;
		}

		// Sailing "Charting Complete!" pop-up. Log-only: the varbit read on the next sync is what
		// actually records it, so nothing is lost if this pop-up is ever missed or reworded.
		if (plainTitle.toLowerCase().startsWith(CHARTING_POPUP_TITLE))
		{
			final String task = body.trim();
			if (!task.isEmpty())
			{
				logSession("Charted: " + task);
				if (chartedSincePost.size() < 20)
				{
					chartedSincePost.add(task);
				}
				log.debug("Waypoint: charting pop-up '{}'", task);
				scheduleSyncCoalesced();
			}
			return;
		}

		// Combat-achievement "Combat Task Completed!" pop-up — capture the finished task live.
		if (title.toLowerCase().contains("combat task") || body.regionMatches(true, 0, "Task Completed:", 0, 15))
		{
			final Matcher m = COMBAT_POPUP_BODY.matcher(body);
			String task = m.find()
				? m.group(1).trim()
				: body.replaceFirst("(?i)^Task Completed:\\s*", "")
					.replaceFirst("\\s*\\(\\d+\\s*points?\\)\\s*$", "").trim();
			if (task.isEmpty())
			{
				return;
			}
			// The pop-up is proof of completion, so record it under the "Complete" filter value —
			// the server marks anything at that value as done. Max-merge so it can't be downgraded.
			caSeen.merge(task, CA_FILTER_COMPLETE, Integer::max);
			logSession("Combat: " + task);
			log.debug("Waypoint: combat task pop-up '{}' captured", task);
			scheduleSyncCoalesced();
			return;
		}

		log.debug("Waypoint: unhandled notification pop-up, title='{}'", title);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE
			&& event.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		final String msg = event.getMessage().replaceAll("<[^>]*>", "").trim();
		final Matcher m = COLLOG_CHAT.matcher(msg);
		if (!m.find())
		{
			return;
		}
		final String item = m.group(1).trim();
		if (item.isEmpty())
		{
			return;
		}
		// -1 marks "confirmed by the game itself", distinct from any opacity value.
		collectionItems.put(item, -1);
		log.debug("Waypoint: collection log gain '{}' (now holding {} item states)",
			item, collectionItems.size());
		scheduleSyncCoalesced();
	}

	/** Read the item grid of whichever collection log page is open. */
	private void captureCollectionItems()
	{
		int added = 0;
		for (int child = 0; child < MAX_INTERFACE_CHILDREN; child++)
		{
			final Widget w = client.getWidget(InterfaceID.COLLECTION, child);
			added += collectItemWidgets(w, 0);
		}
		if (added > 0)
		{
			log.debug("Waypoint: read {} collection item(s) from the open page ({} held)",
				added, collectionItems.size());
		}
	}

	private int collectItemWidgets(Widget w, int depth)
	{
		if (w == null || depth > 8)
		{
			return 0;
		}
		int added = 0;
		final int itemId = w.getItemId();
		if (itemId > 0)
		{
			try
			{
				final String name = client.getItemDefinition(itemId).getName();
				if (name != null && !name.isEmpty() && !"null".equals(name))
				{
					// Never downgrade a chat-confirmed entry (-1) to an opacity reading.
					final Integer prev = collectionItems.get(name);
					if (prev == null || prev != -1)
					{
						if (collectionItems.put(name, w.getOpacity()) == null)
						{
							added++;
						}
					}
				}
			}
			catch (Exception ignored)
			{
			}
		}
		for (Widget[] kids : new Widget[][]{ w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren() })
		{
			if (kids != null)
			{
				for (Widget k : kids)
				{
					added += collectItemWidgets(k, depth + 1);
				}
			}
		}
		return added;
	}

	private void captureCollectionPage()
	{
		// Scan the group's children, not just child 0. The page heading, category list and
		// "Obtained:" line are siblings of child 0 rather than descendants of it.
		//
		// Text is collected in document order because the heading renders immediately above
		// "Obtained: x/y" and is taken as the nearest preceding label. A stack-based walk reverses
		// that adjacency and picks up decoration instead.
		final java.util.List<String> seenText = new java.util.ArrayList<>();
		for (int group : new int[]{ InterfaceID.COLLECTION, InterfaceID.COLLECTION_OVERVIEW })
		{
			for (int child = 0; child < MAX_INTERFACE_CHILDREN; child++)
			{
				collectText(client.getWidget(group, child), seenText, 0);
			}
		}
		if (seenText.isEmpty())
		{
			return;
		}

		String title = null;
		int obtained = -1, total = -1;
		int overallObtained = -1, overallTotal = -1;
		int obtainedAt = -1;

		for (int i = 0; i < seenText.size(); i++)
		{
			final String text = seenText.get(i);
			final Matcher m = OBTAINED.matcher(text);
			if (m.find() && obtainedAt < 0)
			{
				obtained = Integer.parseInt(m.group(1));
				total = Integer.parseInt(m.group(2));
				obtainedAt = i;
				continue;
			}
			final Matcher h = HEADER.matcher(text);
			if (h.find())
			{
				overallObtained = Integer.parseInt(h.group(1));
				overallTotal = Integer.parseInt(h.group(2));
			}
		}
		// Remember the collection log's overall count so the panel can show a real total instead of
		// a per-session "pages captured" number that reads as 0 when nothing new was opened.
		if (overallObtained >= 0 && overallTotal > 0)
		{
			lastCollObtained = overallObtained;
			lastCollTotal = overallTotal;
		}

		// The overview lists the five top-level groups with their totals, laid out as all five
		// labels followed by all five counts, not as label/count pairs. Scanning forward from a
		// label for a nearby count therefore mis-assigns them. Collect labels and counts
		// separately in document order and pair them by position.
		final java.util.List<String> groupLabels = new java.util.ArrayList<>();
		final java.util.List<int[]> groupCounts = new java.util.ArrayList<>();
		for (final String text : seenText)
		{
			if (GROUPS.contains(text) && !groupLabels.contains(text))
			{
				groupLabels.add(text);
				continue;
			}
			if (HEADER.matcher(text).find())
			{
				continue;   // "Collection Log - 61/1706" is the window title, not a group
			}
			final Matcher cm = COUNT.matcher(text);
			if (cm.matches())
			{
				groupCounts.add(new int[]{ Integer.parseInt(cm.group(1)), Integer.parseInt(cm.group(2)) });
			}
		}
		// Only accept it when the shape is right: five labels and at least five counts.
		if (groupLabels.size() == GROUPS.size() && groupCounts.size() >= groupLabels.size())
		{
			for (int i = 0; i < groupLabels.size(); i++)
			{
				final JsonObject grp = new JsonObject();
				grp.addProperty("obtained", groupCounts.get(i)[0]);
				grp.addProperty("total", groupCounts.get(i)[1]);
				collectionGroups.put(groupLabels.get(i), grp);
			}
		}

		// Walk back from the count to the page heading, skipping decoration.
		for (int i = obtainedAt - 1; i >= 0 && title == null; i--)
		{
			final String t = seenText.get(i);
			if (t.length() < 3 || t.length() > 40) continue;   // '*', scrollbar glyphs, prose
			if (t.indexOf(':') >= 0) continue;                 // "Personal Best: 9:25" etc.
			if (HEADER.matcher(t).find()) continue;            // the window header
			if (t.equalsIgnoreCase("Search")) continue;        // the search button
			title = t;
		}

		if (collectionGroups.isEmpty())
		{
			// Report which screen is open and what is on it, keyed so it logs once per screen.
			final String sig = "screen:" + seenText.size() + ":" + (seenText.isEmpty() ? "" : seenText.get(0));
			if (!sig.equals(lastScreenSig))
			{
				lastScreenSig = sig;
				log.debug("Waypoint: collection screen open (COLLECTION={}, OVERVIEW={}), no group "
						+ "totals found. First 25 strings: {}",
					interfaceOpen(InterfaceID.COLLECTION), interfaceOpen(InterfaceID.COLLECTION_OVERVIEW),
					seenText.size() > 25 ? seenText.subList(0, 25) : seenText);
			}
		}

		if (!collectionGroups.isEmpty())
		{
			final String sig = collectionGroups.toString();
			if (!sig.equals(lastGroupsSig))
			{
				lastGroupsSig = sig;
				log.debug("Waypoint: captured collection overview {}", collectionGroups.keySet());
				scheduleSyncCoalesced();
			}
		}

		if (title == null || title.isEmpty() || obtained < 0)
		{
			// Log the failure rather than returning silently, so a bad parse is distinguishable
			// from the event never firing.
			log.debug("Waypoint: collection page unreadable (title={}, obtained={}, overall={}/{}). "
					+ "Text widgets found: {}",
				title, obtained, overallObtained, overallTotal,
				seenText.size() > 60 ? seenText.subList(0, 60) : seenText);
			return;
		}

		final JsonObject page = new JsonObject();
		page.addProperty("obtained", obtained);
		page.addProperty("total", total);
		// Which of the five tabs this page belongs to, taken from COLLECTION_LAST_TAB rather than
		// inferred from the title. Matching titles against the flag keys misses most raids.
		final int tab = client.getVarbitValue(VarbitID.COLLECTION_LAST_TAB);
		if (tab >= 0 && tab < TAB_NAMES.length)
		{
			page.addProperty("group", TAB_NAMES[tab]);
		}
		final JsonObject prev = collectionPages.put(title, page);
		if (prev != null && prev.toString().equals(page.toString()))
		{
			return;   // identical to what is already held, nothing to send
		}
		log.debug("Waypoint: captured collection page '{}' {}/{}", title, obtained, total);
		scheduleSyncCoalesced();
	}

	/** Reading quest state touches varbits, so it must run on the client thread. */
	private void scheduleSync(int delaySeconds)
	{
		if (delaySeconds <= 0)
		{
			clientThread.invokeLater(this::syncNow);
		}
		else
		{
			executor.schedule(() -> clientThread.invokeLater(this::syncNow),
				delaySeconds, TimeUnit.SECONDS);
		}
	}

	/** How long to wait for a burst of captures to finish before pushing them as one sync. */
	private static final int BURST_COALESCE_SECONDS = 15;

	private ScheduledFuture<?> burstSync;

	/**
	 * Sync after a capture, coalescing rapid ones into a single request.
	 *
	 * Each payload is the account's FULL state, so firing one per captured event is wasteful the
	 * moment events arrive in bursts. Sea charting made that obvious: a charting run completes a
	 * task every 20-30 seconds, and a sync each time pushed the same few hundred KB over and over
	 * — enough to trip the server's own rate limit during ordinary play, which then rejected syncs
	 * for the rest of the hour.
	 *
	 * The first capture in a burst schedules the sync; anything captured while that is pending
	 * rides along with it, because the payload is rebuilt at send time and so already includes
	 * them. Nothing is dropped and nothing is delayed by more than the window.
	 *
	 * Login, the periodic timer and the panel's "Sync now" button all stay immediate — those are
	 * single events, not bursts.
	 */
	private synchronized void scheduleSyncCoalesced()
	{
		if (burstSync != null && !burstSync.isDone())
		{
			return;   // one is already queued; this capture will be in that payload
		}
		burstSync = executor.schedule(() -> clientThread.invokeLater(this::syncNow),
			BURST_COALESCE_SECONDS, TimeUnit.SECONDS);
	}

	/**
	 * One varbit to read, paired with the key it is emitted under.
	 *
	 * The plugin hub does not allow reflection, so the varbit groups below are listed explicitly
	 * rather than discovered by scanning {@code VarbitID} fields. The keys match exactly what the
	 * old prefix/suffix scan produced, so the server payload is unchanged. Because VarbitID
	 * constants are compile-time {@code static final int}s, each reference is inlined into the
	 * bytecode: reading these never loads the VarbitID class, which also sidesteps the gameval
	 * class-shadowing hazard that {@link #safeGroup} guards against.
	 */
	private static final class VE
	{
		final String key;
		final int id;

		VE(String key, int id)
		{
			this.key = key;
			this.id = id;
		}
	}

	private JsonObject readVarbitEntries(VE[] entries)
	{
		final JsonObject out = new JsonObject();
		for (VE e : entries)
		{
			out.addProperty(e.key, client.getVarbitValue(e.id));
		}
		return out;
	}

