	/**
	 * All 24 skills with real (unboosted) level and exact xp.
	 *
	 * Saves the server an outbound hiscores lookup per user, and is fresher than the hiscores,
	 * which lag behind actual play.
	 */
	private JsonObject readSkills()
	{
		final JsonObject out = new JsonObject();
		for (Skill skill : Skill.values())
		{
			try
			{
				final JsonObject s = new JsonObject();
				s.addProperty("level", client.getRealSkillLevel(skill));
				s.addProperty("xp", client.getSkillExperience(skill));
				out.add(skill.getName(), s);
			}
			catch (Exception ignored)
			{
				// A skill this revision doesn't know: skip rather than send a zero.
			}
		}
		return out;
	}

	private void syncNow()
	{

		// getLocalPlayer() stays null briefly after LOGGED_IN, and quest varbits are not ready
		// while it is.
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			pendingQuestsJson = null;
			return;
		}
		if (config.token() == null || config.token().isEmpty())
		{
			log.debug("Waypoint: no token configured, skipping");
			statusText = "No token set — paste one in the plugin settings.";
			refreshPanel();
			return;
		}

		final JsonObject quests = new JsonObject();
		for (Quest quest : Quest.values())
		{
			try
			{
				QuestState state = quest.getState(client);
				quests.addProperty(quest.getName(), state.name()); // FINISHED / IN_PROGRESS / NOT_STARTED
			}
			catch (Exception ex)
			{
				// a few enum entries may not resolve on all revisions; skip them
			}
		}

		if (quests.size() == 0)
		{
			return; // nothing readable yet
		}

		// Achievement diaries (12 areas x 4 tiers) and combat achievement tiers. CA is tier-level
		// only here, since per-task completion is not exposed as a varbit.
		final JsonObject diaries = safeGroup("achievement diaries", this::readDiaries);
		// Karamja EASY/MEDIUM/HARD have task counters but no completion varbit. Sending the
		// counters lets the server show real progress rather than a wrong tick.
		final JsonObject diaryCounts = safeGroup("karamja counters",
			() -> readVarbitEntries(KARAMJA_COUNT_VARBITS));
		final JsonObject combat = safeGroup("combat tiers", () -> readTiers(CA_TIER_STATUS));
		final JsonObject combatCounts = safeGroup("combat counts", () -> readTiers(CA_TIER_COUNT));
		final JsonObject collection = safeGroup("collection log flags",
			() -> readVarbitEntries(COLLECTION_VARBITS));
		final JsonObject charting = safeGroup("charting", () -> readVarbitEntries(CHARTING_VARBITS));
		final JsonObject skills = safeGroup("skills", this::readSkills);
		final JsonObject caTasks = new JsonObject();
		caSeen.forEach(caTasks::addProperty);
		final JsonArray caTaskBits = combatTaskBits();
		final JsonObject collectionPagesJson = new JsonObject();
		collectionPages.forEach(collectionPagesJson::add);
		final JsonObject collectionGroupsJson = new JsonObject();
		collectionGroups.forEach(collectionGroupsJson::add);

		// Change detection and the stability check have to cover everything that gets sent, or a
		// diary completed with no quest change would never sync.
		final String questsJson = quests.toString() + diaries + diaryCounts + combat + combatCounts
			+ collection + collectionPagesJson + collectionGroupsJson + skills + caTasks
			+ caTaskBits + collectionItems + charting
			+ (clogComplete == null ? "" : "clog:" + clogComplete.size());

		// Two consecutive identical reads are required before a snapshot is trusted. A client
		// still streaming quest varbits produces a different result each time, so a half-loaded
		// state cannot satisfy this.
		if (!questsJson.equals(pendingQuestsJson))
		{
			pendingQuestsJson = questsJson;
			log.debug("Waypoint: reading not yet stable, re-checking in {}s", CONFIRM_DELAY_SECONDS);
			scheduleSync(CONFIRM_DELAY_SECONDS);
			return;
		}

		// Current totals for the panel — real numbers, so nothing reads as a misleading 0. Miniquests
		// (see MINIQUESTS) are counted on their own line, not mixed into the quest total.
		// Recipe for Disaster is ONE quest in-game but 11 separate "Recipe for Disaster - X" enum
		// entries; the game counts it once (when the Culinaromancer part is finished), so we do too.
		final boolean rfdDone = "FINISHED".equals(questState(quests, RFD_FINAL));
		int questsDone = 0, miniDone = 0;
		for (String qn : quests.keySet())
		{
			if (!"FINISHED".equals(quests.get(qn).getAsString()))
			{
				continue;
			}
			if (MINIQUESTS.contains(qn))
			{
				miniDone++;
			}
			else if (!qn.startsWith(RFD_PREFIX))
			{
				questsDone++;
			}
		}
		if (rfdDone)
		{
			questsDone++;
		}
		final int combatTotal = safeInt(this::completedTaskCount);
		accountText = client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null
			? client.getLocalPlayer().getName() : "";
		if (questsJson.equals(lastQuestsJson))
		{
			// Nothing changed since the last successful post → the account is fully mirrored. Leave
			// the "what's new" list showing the last thing that DID sync (the green "Everything
			// synced" in the card already signals up-to-date); overwriting it here is what wiped the
			// quest name a moment after it appeared.
			lastChartLine = chartLine(charting);
			detailsText = buildStatsHtml(questsDone, miniDone, combatTotal, collLine(), skills.size(),
				lastChartLine, SYNC_OK);
			lastSyncAt = System.currentTimeMillis();
			statusText = "Up to date";
			refreshPanel();
			return;
		}
		// Something changed and is about to be posted.
		lastChartLine = chartLine(charting);
		detailsText = buildStatsHtml(questsDone, miniDone, combatTotal, collLine(), skills.size(),
			lastChartLine, SYNC_BUSY);

		final JsonObject payload = new JsonObject();
		if (client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null)
		{
			payload.addProperty("rsn", client.getLocalPlayer().getName());
		}
		// The character name above is the only thing identifying which character this sync belongs
		// to. One Waypoint account can track several, and the server files each sync under the name
		// it came from.
		//
		// client.getAccountHash() would be the more robust key — it is stable across renames, where
		// the name is not — but it is a permanent unique identifier for a Jagex account, and this
		// plugin deliberately does not send one to a third-party server. A rename is handled on the
		// site instead ("Changed your name?"), which costs one manual step and keeps the identifier
		// out of the payload entirely.
		//
		// Account type, which changes what advice is even possible. No ironman can use the Grand
		// Exchange, so the site's whole standard money-making list is inapplicable to them; an
		// ULTIMATE ironman additionally has no bank, which rules out most of what is left. Group
		// ironmen can trade within their group. Sending the exact mode rather than a yes/no keeps
		// those distinctions available to the recommendations.
		payload.addProperty("accountType", client.getVarbitValue(VarbitID.IRONMAN));
		payload.add("quests", quests);
		payload.add("diaries", diaries);
		payload.add("diaryCounts", diaryCounts);
		payload.add("combat", combat);
		payload.add("combatCounts", combatCounts);
		payload.add("collection", collection);
		payload.add("charting", charting);
		// The wording of anything charted since the last successful post — see chartedSincePost.
		synchronized (chartedSincePost)
		{
			if (!chartedSincePost.isEmpty())
			{
				final JsonArray arr = new JsonArray();
				for (String c : chartedSincePost)
				{
					arr.add(c);
				}
				payload.add("chartedNow", arr);
			}
		}
		payload.add("collectionPages", collectionPagesJson);
		payload.add("collectionGroups", collectionGroupsJson);
		final JsonObject colItems = new JsonObject();
		collectionItems.forEach(colItems::addProperty);
		payload.add("collectionItems", colItems);
		// A finished transmit is the whole collection log, so the server may replace rather than
		// merge — which is the only way a wrongly-set flag ever gets cleared. Absent until one has
		// completed this session, so an ordinary sync never claims to be a total.
		if (clogComplete != null)
		{
			final JsonArray obtained = new JsonArray();
			clogComplete.forEach(obtained::add);
			payload.add("collectionObtained", obtained);
			payload.addProperty("collectionComplete", true);
		}
		payload.add("skills", skills);
		payload.add("caTasks", caTasks);
		payload.add("caTaskVarps", caTaskBits);
		payload.addProperty("caTaskCount", combatTotal);

		// Log newly-completed quests to the running session log (combat tasks and collection items
		// add themselves live from their pop-ups). The log persists for the session — a later
		// no-change sync never wipes it.
		logNewQuests(quests);
		serverText = buildSessionLogHtml();
		pendingQuestStates = snapshotStates(quests);

		statusText = "Syncing…";
		refreshPanel();

		post(payload, questsJson);
	}

	/**
	 * Where to sync to. Fixed at {@link #DEFAULT_URL} — deliberately not overridable at runtime, so
	 * the destination of everything this plugin sends is the one visible in this source file. To
	 * run against a local server during development, change DEFAULT_URL and rebuild.
	 */
	static String baseUrl()
	{
		return DEFAULT_URL.replaceAll("/+$", "");
	}

	private void post(JsonObject payload, String questsJson)
	{
		final String base = baseUrl();
		final Request request = new Request.Builder()
			.url(base + "/api.php?do=ingest")
			.header("Authorization", "Bearer " + config.token())
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(@Nonnull Call call, @Nonnull IOException e)
			{
				statusText = "Couldn't reach the server.";
				refreshPanel();
				log.warn("Waypoint: request failed", e);
			}

			@Override
			public void onResponse(@Nonnull Call call, @Nonnull Response response)
			{
				try (ResponseBody body = response.body())
				{
					final String bodyStr = body != null ? body.string() : "";
					if (response.isSuccessful())
					{
						lastQuestsJson = questsJson; // only cache on success
						chartedSincePost.clear();    // paired up server-side, safe to forget
						lastSyncAt = System.currentTimeMillis();
						statusText = "Synced ✓";
						// Promote this payload to the baseline so the next "what's new" diffs against it.
						if (pendingQuestStates != null)
						{
							prevQuestStates = pendingQuestStates;
						}
						// Show the server's authoritative stored totals — this is how the collection
						// count appears without the player re-opening the log in-game.
						try
						{
							final JsonObject r = gson.fromJson(bodyStr, JsonObject.class);
							if (r != null && r.has("stored") && r.get("stored").isJsonObject())
							{
								final JsonObject s = r.getAsJsonObject("stored");
								srvQuests = optInt(s, "quests", srvQuests);
								srvMini = optInt(s, "miniquests", srvMini);
								srvCombat = optInt(s, "combat", srvCombat);
								srvColl = optInt(s, "collection", srvColl);
								srvSkills = optInt(s, "skills", srvSkills);
								if (srvQuests >= 0)
								{
									detailsText = buildStatsHtml(srvQuests, srvMini, srvCombat, collLine(),
										srvSkills, lastChartLine, SYNC_OK);
								}
							}
						}
						catch (RuntimeException ignore)
						{
							// Fall back to the plugin-side totals already shown.
						}
						log.debug("Waypoint: synced ({})", bodyStr);
					}
					else
					{
						// A rejected payload is NOT delivered, so the snapshot is deliberately not
						// promoted here. It used to be, on the reasoning that retrying immediately
						// was what caused the throttle — but that made a throttled sync look
						// successful, and the progress in it then waited for some unrelated change
						// before being sent again. Bursts are handled properly now
						// (scheduleSyncCoalesced), so leaving it unpromoted just means the next
						// periodic sync resends it, which is the correct behaviour.
						statusText = "Sync failed (" + response.code() + ")";
						// Show what the server actually said. It already sends a plain-English
						// reason ("no character name in the payload, nothing was synced"), and
						// hiding it left the panel reading only "Sync failed (422)" — a number
						// nobody can act on. Parsed from the response we already read, so this
						// costs no extra request.
						serverText = "";
						try
						{
							final JsonObject err = gson.fromJson(bodyStr, JsonObject.class);
							if (err != null && err.has("error") && err.get("error").isJsonPrimitive())
							{
								String msg = err.get("error").getAsString();
								// Bounded: this is server-supplied text going into a Swing label,
								// and an unbounded string would stretch the panel.
								if (msg.length() > 300)
								{
									msg = msg.substring(0, 300) + "…";
								}
								// Same width-boxed HTML the session log uses, so the message WRAPS
								// instead of forcing the sidebar wider — and escaped, because this
								// is server-supplied text going into a label that renders HTML.
								serverText = "<html><div style='width:190px'>" + htmlEscape(msg) + "</div></html>";
							}
						}
						catch (RuntimeException ignore)
						{
							// Not JSON (a proxy error page, say) — leave the status code alone.
						}
						log.warn("Waypoint: server returned {} {}", response.code(), bodyStr);
					}
				}
				catch (IOException e)
				{
					statusText = "Error reading the server response.";
					log.warn("Waypoint: error reading response", e);
				}
				refreshPanel();
			}
		});
	}
}

package com.waypointrs.sync;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("waypointsync")
public interface WaypointSyncConfig extends Config
{
	/**
	 * The only value a user supplies. There is no URL setting and no runtime override of any kind:
	 * everyone syncs to the hosted app, at the address fixed in WaypointSyncPlugin.baseUrl().
	 *
	 * secret = true masks the field in the settings panel and keeps it out of RuneLite's config
	 * export and profile sync. The token is a bearer credential for one Waypoint account, so
	 * anyone holding it can overwrite that account's progress.
	 */
	@ConfigItem(
		keyName = "token",
		name = "Plugin token",
		description = "Paste the token from Waypoint: Import > Auto-sync > Generate. "
			+ "Nothing is uploaded until this is set.",
		secret = true,
		position = 1
	)
	default String token()
	{
		return "";
	}

	@ConfigItem(
		keyName = "syncOnLogin",
		name = "Sync on login",
		description = "Automatically sync quests when you log in",
		position = 3
	)
	default boolean syncOnLogin()
	{
		return true;
	}

	@ConfigItem(
		keyName = "loginDelaySeconds",
		name = "Login sync delay (sec)",
		description = "Wait this long after login before the first sync. Quest varbits are not "
			+ "loaded the instant you log in, so syncing immediately under-reports completed "
			+ "quests.",
		position = 4
	)
	default int loginDelaySeconds()
	{
		return 30;
	}

	@ConfigItem(
		keyName = "syncIntervalMinutes",
		name = "Re-sync every (min)",
		description = "How often to re-sync during a session (0 to disable periodic sync)",
		position = 5
	)
	default int syncIntervalMinutes()
	{
		return 5;
	}
}
